import datetime
def month_stats(series):
    out = {}
    for ts, v in series.items():
        dt = datetime.datetime.strptime(ts, "%Y-%m-%dT%H:%M:%S")
        k = (dt.year, dt.month)
        out.setdefault(k, []).append(v)
    return {k: (len(v), sum(v)/len(v)) for k,v in sorted(out.items())}

for z, tid in zones.items():
    ms = month_stats(data[tid])
    # Just print 2018 monthly averages
    row = []
    for k in ms:
        if k[0]==2018:
            row.append(f"{k[1]}:{ms[k][1]:.1f}(n={ms[k][0]})")
    print(z, " ".join(row))

